CREATE TABLE IF NOT EXISTS employee_leave_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE, leave_type text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, days numeric(6,2), reason text, status text NOT NULL DEFAULT 'pending', approved_by uuid REFERENCES workforce_employees(id), created_at timestamptz NOT NULL DEFAULT now());